G,EACR,KAAK,EAAC,KAAK,EACX,OAAO,EAAE,kBAAkB,EAC3B,OAAO,EAAE,OAAO,EAChB,SAAS,EAAE,CAAC,CAAC,cAAc,EAAE,EAAC,MAAM,EAAC,CAAC,KAClC,gBAAgB,YAEnB,eAAe,GACX,EACR,SAAS,IAAI,CACV,uBAAC,aAAK,IACF,IAAI,EAAE,SAAS,EACf,YAAY,EAAE,gBAAgB,EAC9B,SAAS,EAAE,eAAe,EAC1B,SAAS,EAAC,KAAK,EACf,aAAa,QACb,QAAQ,kBAER,gCAAK,SAAS,EAAE,CAAC,CAAC,OAAO,CAAC,YAAG,SAAS,GAAO,GACzC,CACX,IACC,CACT,CAAC;IAEF,MAAM,OAAO,GAAG,CAAC,GAAG,EAAE;QAClB,IAAI,aAAa,EAAE,CAAC;YAChB,OAAO,aAAa,CAAC,WAAW,EAAE,YAAY,CAAC,CAAC;QACpD,CAAC;QAED,IAAI,CAAC,gBAAgB,IAAI,CAAC,eAAe,EAAE,CAAC;YACxC,OAAO,IAAI,CAAC;QAChB,CAAC;QAED,OAAO,CACH,wBAAC,KAAK,CAAC,QAAQ,eACV,gBAAgB,IAAI,YAAY,EAChC,eAAe,IAAI,WAAW,IAClB,CACpB,CAAC;IACN,CAAC,CAAC,EAAE,CAAC;IAEL,IAAI,CAAC,OAAO,IAAI,CAAC,QAAQ,EAAE,CAAC;QACxB,OAAO,IAAI,CAAC;IAChB,CAAC;IAED,OAAO,CACH,iCAAK,SAAS,EAAE,CAAC,CAAC,IAAI,EAAE,SAAS,CAAC,aAC7B,QAAQ,IAAI,gCAAK,SAAS,EAAE,CAAC,CAAC,UAAU,CAAC,YAAG,QAAQ,GAAO,EAC3D,OAAO,IAAI,gCAAK,SAAS,EAAE,CAAC,CAAC,aAAa,CAAC,YAAG,OAAO,GAAO,IAC3D,CACT,CAAC;AACN,CAAC","sourcesContent":["'use client';

import * as React from 'react';

import type {UseFloatingOptions} from '@floating-ui/react';

import {useForkRef} from '../../../hooks';
import {Button} from '../../Button';
import type {ButtonButtonProps, ButtonLinkProps, ButtonView} from '../../Button';
import {Popup} from '../../Popup';
import {block} from '../../utils/cn';
import {DialogPrivateContext} from '../DialogPrivateContext';

import './DialogFooter.scss';

const b = block('dialog-footer');

type ButtonPreset = 'default' | 'success' | 'danger';

interface DialogFooterOwnProps {
    onClickButtonApply?: (event: React.MouseEvent<HTMLElement, MouseEvent> | KeyboardEvent) => void;
    onClickButtonCancel?: (event: React.MouseEvent<HTMLElement, MouseEvent>) => void;
    textButtonCancel?: string;
    textButtonApply?: string;
    propsButtonCancel?: ButtonButtonProps | ButtonLinkProps;
    propsButtonApply?: ButtonButtonProps | ButtonLinkProps;
    loading?: boolean;
    children?: React.ReactNode;
    errorText?: string;
    renderButtons?: (
        buttonApply: React.ReactNode,
        buttonCancel: React.ReactNode,
    ) => React.ReactNode;
    className?: string;
}

interface DialogFooterDefaultProps {
    preset: ButtonPreset;
    showError: boolean;
}

// TODO: Оно точно нужно?
function getButtonView(preset: ButtonPreset): ButtonView {
    switch (preset) {
        case 'default':
            return 'action';
        case 'success':
            return 'action';
        case 'danger':
            return 'action';
        default:
            return 'action';
    }
}

export type DialogFooterProps = DialogFooterOwnProps & Partial<DialogFooterDefaultProps>;

export function DialogFooter(props: DialogFooterProps) {
    const {
        onClickButtonCancel,
        onClickButtonApply,
        loading,
        textButtonCancel,
        textButtonApply,
        propsButtonCancel,
        propsButtonApply,
        preset = 'default',
        children,
        errorText,
        showError = false,
        renderButtons,
        className,
    } = props;

    const {initialFocusRef, initialFocusAction, onTooltipEscapeKeyDown} =
        React.useContext(DialogPrivateContext);

    const errorTooltipRef = React.useRef<HTMLButtonElement>(null);
    const apllyBtnRef = useForkRef(
        errorTooltipRef,
        initialFocusAction === 'apply' ? initialFocusRef : null,
    );
    const cancelBtnRef = useForkRef(initialFocusAction === 'cancel' ? initialFocusRef : null);

    const buttonCancel = (
        <div className={b('button', {action: 'cancel'})}>
            <Button
                ref={cancelBtnRef}
                view={textButtonApply ? 'flat' : 'normal'}
                size="l"
                width="max"
                onClick={onClickButtonCancel}
                disabled={loading}
                {...propsButtonCancel}
            >
                {textButtonCancel}
            </Button>
        </div>
    );

    const handleOpenChange = React.useCallback<NonNullable<UseFloatingOptions['onOpenChange']>>(
        (isOpen, event, reason) => {
            if (!isOpen && event && reason === 'escape-key') {
                onTooltipEscapeKeyDown?.(event as KeyboardEvent);
            }
        },
        [onTooltipEscapeKeyDown],
    );

    const buttonApply = (
        <div className={b('button', {action: 'apply'})}>
            <Button
                ref={apllyBtnRef}
                type="submit"
                view={getButtonView(preset)}
                size="l"
                width="max"
                onClick={onClickButtonApply}
                loading={loading}
                className={b('button-apply', {preset})}
                {...propsButtonApply}
            >
                {textButtonApply}
            </Button>
            {errorText && (
                <Popup
                    open={showError}
                    onOpenChange={handleOpenChange}
                    anchorRef={errorTooltipRef}
                    placement="top"
                    disablePortal
                    hasArrow
                >
                    <div className={b('error')}>{errorText}</div>
                </Popup>
            )}
        </div>
    );

    const buttons = (() => {
        if (renderButtons) {
            return renderButtons(buttonApply, buttonCancel);
        }

        if (!textButtonCancel && !textButtonApply) {
            return null;
        }

        return (
            <React.Fragment>
                {textButtonCancel && buttonCancel}
                {textButtonApply && buttonApply}
            </React.Fragment>
        );
    })();

    if (!buttons && !children) {
        return null;
    }

    return (
        <div className={b(null, className)}>
            {children && <div className={b('children')}>{children}</div>}
            {buttons && <div className={b('bts-wrapper')}>{buttons}</div>}
        </div>
    );
}
"]}

